        #[arg(short, long, help = "Mark the time entry as billable")]
        billable: bool,
        #[arg(
            long,
            help = "Start date/time. Accepted formats: RFC3339, YYYY-MM-DD HH:MM[:SS], YYYY-MM-DDTHH:MM[:SS], YYYY-MM-DD, HH:MM[:SS]"
        )]
        start: Option<String>,
        #[arg(
            long,
            help = "End date/time. Requires --start. Accepted formats: RFC3339, YYYY-MM-DD HH:MM[:SS], YYYY-MM-DDTHH:MM[:SS], YYYY-MM-DD, HH:MM[:SS]"
        )]
        end: Option<String>,
        #[arg(short, long, help = "Output in JSON format")]
        json: bool,
    },
    /// Continue a previous time entry.
  toggl report weekly
  toggl report weekly --since today --until today
  toggl report weekly --since 2026-03-17 --until 2026-03-23 --json")]
    Weekly {
        #[arg(
            long,
            help = "Start date (YYYY-MM-DD, or: today, yesterday, now, this_week, last_week). Default: this_week"
        )]
        since: Option<String>,
        #[arg(
            long,
            help = "End date (YYYY-MM-DD, or: today, yesterday, now, this_week, last_week). Default: today"
        )]
        until: Option<String>,
        #[arg(short, long, help = "Output in JSON format")]
        json: bool,
    },
}

impl Command {
    /// Returns true if the parsed command includes a `--json` output flag.
    /// Used by the top-level error handler to format errors as JSON when appropriate.
    pub fn has_json_flag(&self) -> bool {
        match self {
            Command::Me { json } => *json,
            Command::Entry { action } => match action {
                EntryAction::Current { json }
                | EntryAction::List { json, .. }
                | EntryAction::Stop { json }
                | EntryAction::Start { json, .. }
                | EntryAction::Resume { json, .. }

use crate::api::client::ApiClient;
use crate::models::{ResultWithDefaultError, TimeEntry};
use crate::utilities;
use chrono::{Datelike, NaiveDate, Utc};
use std::collections::BTreeMap;

pub struct BillWeeklyCommand;

/// A stopped billable entry contributes its recorded duration to the invoice.
/// Keep this as the single billing rule so other billing views can reuse it.
fn billable_seconds(entry: &TimeEntry) -> Option<i64> {
    if entry.billable && !entry.is_running() && entry.duration >= 0 {
        Some(entry.duration)
    } else {
        None
    }
}

fn week_monday(entry: &TimeEntry) -> NaiveDate {
    let date = entry.start.with_timezone(&Utc).date_naive();
    date - chrono::Duration::days(date.weekday().num_days_from_monday() as i64)
}

fn weekly_totals(entries: &[TimeEntry]) -> BTreeMap<NaiveDate, i64> {
    let mut totals = BTreeMap::new();
    for entry in entries {
        if let Some(seconds) = billable_seconds(entry) {
            *totals.entry(week_monday(entry)).or_insert(0) += seconds;
        }
    }
    totals
}

impl BillWeeklyCommand {
    pub async fn execute(
        api_client: impl ApiClient,
        since: Option<String>,
        until: Option<String>,
    ) -> ResultWithDefaultError<()> {
        let entries = if since.is_some() || until.is_some() {
            let (since, until) = utilities::normalize_time_entry_list_filters(since, until)?;
            api_client
                .get_time_entries_filtered_minimal(since, until)
                .await?
        } else {
            api_client.get_entities().await?.time_entries
        };

        let totals = weekly_totals(&entries);
        if totals.is_empty() {
            println!("(no data)");
            return Ok(());
        }

        let grand_total: i64 = totals.values().sum();
        for (monday, seconds) in totals {
            println!("{}  {}s", monday.format("%Y-%m-%d"), seconds);
        }
        println!("Total  {grand_total}s");
        Ok(())
    }
}

