    #[test]
    fn groups_billable_stopped_entries_by_utc_iso_week() {
        let entries = vec![
            entry(
                "2026-01-04T23:30:00Z",
                10,
                true,
                Some("2026-01-05T00:00:00Z"),
            ),
            entry(
                "2026-01-05T00:30:00Z",
                20,
                true,
                Some("2026-01-05T01:00:00Z"),
            ),
            entry(
                "2026-01-06T00:00:00Z",
                30,
                false,
                Some("2026-01-06T01:00:00Z"),
            ),
            entry("2026-01-07T00:00:00Z", -1, true, None),
        ];

        let totals = weekly_totals(&entries);
        assert_eq!(
            totals.get(&NaiveDate::from_ymd_opt(2025, 12, 29).unwrap()),
            Some(&10)
        );
        assert_eq!(
            totals.get(&NaiveDate::from_ymd_opt(2026, 1, 5).unwrap()),
            Some(&20)
        );
    }
